56	/// What a framing follows (VR-26).
57	#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
58	#[serde(rename_all = "snake_case")]
59	pub enum FramingFollow {
60	    Subject,
61	    Face,
62	    Person,
63	    Salient,
64	    Cursor,
65	    Layout,
66	    Speaker,
67	    Center,
68	    Fit,
69	    Keep,
70	}
71	
72	impl FramingFollow {
73	    fn following(self) -> Option<Follow> {
74	        match self {
75	            Self::Subject => Some(Follow::Subject),
76	            Self::Face => Some(Follow::Face),
77	            Self::Person => Some(Follow::Person),
78	            Self::Salient => Some(Follow::Salient),
79	            Self::Cursor | Self::Layout | Self::Speaker | Self::Center | Self::Fit | Self::Keep => {
80	                None
81	            }
82	        }
83	    }
84	
85	    /// The kinds that read `subjects`: the following kinds, `cursor` and
86	    /// `speaker`.
87	    fn reads_subjects(self) -> bool {
88	        self.following().is_some() || matches!(self, Self::Cursor | Self::Speaker)
89	    }
90	}
