96	/// `reframe_clip`'s arguments, in the row's order.
97	#[derive(Debug, Clone, PartialEq)]
98	pub struct Reframe {
99	    pub clip: u32,
100	    pub follow: FramingFollow,
101	    pub zoom: Option<f64>,
102	    pub where_empty: Option<WhereEmpty>,
103	    pub from_width: Option<u32>,
104	    pub from_height: Option<u32>,
105	    pub backdrop: Option<u32>,
106	    pub replace: Option<bool>,
107	    pub mics: Option<Vec<u32>>,
108	    pub mic_faces: Option<Vec<u32>>,
109	    pub subjects: Option<Subjects>,
110	}
