134	impl Project {
135	    /// The op (spec §11 VR-26; this module's doc, and `edit.rs`'s row).
136	    pub fn reframe_clip(&self, r: &Reframe) -> Result<Outcome, String> {
137	        let clip = self.require_clip(r.clip)?.clone();
138	        if let Some(z) = r
139	            .zoom
140	            .filter(|z| !(z.is_finite() && (1.0..=4.0).contains(z)))
141	        {
142	            return Err(format!("zoom must be between 1 and 4 times fill, not {z}"));
143	        }
144	        for (key, value) in [("from_width", r.from_width), ("from_height", r.from_height)] {
145	            if value == Some(0) {
146	                return Err(format!("{key} must be greater than 0, not 0"));
147	            }
148	        }
149	        if let Some(track) = r.backdrop {
150	            self.require_track(track)?;
151	        }
152	        if r.follow == FramingFollow::Speaker {
153	            for &mic in r.mics.iter().flatten() {
154	                self.require_clip(mic)?;
155	            }
156	        }
157	        match self.refusal(&clip, r) {
158	            Some(why) => Ok(Outcome::Refused(why)),
159	            None => self.reframed(&clip, r),
160	        }
161	    }
162	
163	    /// Refusals (1)–(6) and (8) of VR-26, in order ((7) removed by VR-27),
164	    /// VR-50's and VR-51's after the nest and still refusals.
165	    fn refusal(&self, clip: &Clip, r: &Reframe) -> Option<String> {
166	        let id = clip.id;
167	        let keep = r.follow == FramingFollow::Keep;
168	        let following = r.follow.reads_subjects();
169	        let kind = match clip.source {
170	            Source::Text => "text",
171	            Source::Shape => "shape",
172	            Source::Graphic => "graphic",
173	            Source::Adjustment => "adjustment",
174	            _ => "",
175	        };
176	        if !kind.is_empty() {
177	            return (!keep).then(|| {
178	                format!(
179	                    "clip {id} is a {kind} clip, with no picture to frame; only keep reframes it"
180	                )
181	            });
182	        }
183	        let picture = match clip.source {
184	            Source::Media { media, .. } | Source::Still { media, .. } => self
185	                .media(media)
186	                .is_some_and(|m| m.has_video && m.kind == MediaKind::Video),
187	            _ => true,
188	        };
189	        let Some((mw, mh)) = self.source_size(clip).filter(|_| picture) else {
190	            return Some(format!("clip {id}'s media has no picture to frame"));
191	        };
192	        let video = clip.video.clone().unwrap_or_default();
193	        let crop = video.crop;
194	        if !(mw - crop.l - crop.r > 0.0
195	            && mh - crop.t - crop.b > 0.0
196	            && video.scale.is_finite()
197	            && video.scale > 0.0)
198	        {
199	            return Some(no_picture(id));
200	        }
201	        if following {
202	            match clip.source {
203	                Source::Nest { .. } => {
204	                    return Some(format!(
205	                        "clip {id} shows a nest, which has no subjects to follow; frame it with \
206	                         center, fit or keep"
207	                    ))
208	                }
209	                Source::Still { .. } | Source::Image { .. } => {
210	                    return Some(format!(
211	                        "clip {id} shows a still picture, which has no subjects to follow; frame \
212	                         it with center, fit or keep"
213	                    ))
214	                }
215	                Source::Media { media, .. } => {
216	                    let cursor = self.media(media).is_some_and(|m| m.cursor.is_some());
217	                    if r.follow == FramingFollow::Cursor && !cursor {
218	                        return Some(no_cursor_file(id));
219	                    }
220	                    if r.follow != FramingFollow::Cursor && cursor {
221	                        return Some(cursor_not_faces(id));
222	                    }
223	                }
224	                _ => {}
225	            }
226	        }
227	        // `layout` re-lays switches that passed CO-62 when made (VR-53 (c)).
228	        if !keep && r.follow != FramingFollow::Layout {
229	            if let Some(why) = self.matte_refusal(clip) {
230	                return Some(why);
231	            }
232	            if let Some(why) = turn_refusal(id, clip, &video) {
233	                return Some(why);
234	            }
235	        }
236	        if r.follow == FramingFollow::Speaker {
237	            let (mics, faces) = (r.mics.as_deref(), r.mic_faces.as_deref());
238	            if let Some(why) = mics_refusal(self, id, mics, faces) {
239	                return Some(why);
240	            }
241	        }
242	        if following {
243	            if let Some(Err(why)) = r.subjects.as_ref().map(check_subjects) {
244	                return Some(why);
245	            }
246	        }
247	        None
248	    }
249	
250	    /// Refusal (5): a matte track's clip, or one a matte cuts.
251	    fn matte_refusal(&self, clip: &Clip) -> Option<String> {
252	        let id = clip.id;
253	        let index = self.track_index(clip.track)?;
254	        if self.tracks[index].matte.is_none() {
255	            let front = self.tracks.get(index + 1)?;
256	            return (matte_target(&self.tracks, front.id) == Some(clip.track)).then(|| {
257	                format!(
258	                    "clip {id} is cut by the matte on track {}, which framing would move it \
259	                     out of; only keep reframes it",
260	                    front.id
261	                )
262	            });
263	        }
264	        Some(format!(
265	            "clip {id} is on a matte track, which framing would move; only keep reframes it"
266	        ))
267	    }
268	
269	    /// Planned, refused (9) and (10), written and finished.
270	    fn reframed(&self, clip: &Clip, r: &Reframe) -> Result<Outcome, String> {
271	        let id = clip.id;
272	        let zoom = r.zoom.unwrap_or(1.0);
273	        let canvas = (self.canvas.width, self.canvas.height);
274	        let from = (r.from_width, r.from_height);
275	        let from = (from.0.unwrap_or(canvas.0), from.1.unwrap_or(canvas.1));
276	        match r.follow {
277	            FramingFollow::Keep => return self.finish(self.kept(id, from)),
278	            FramingFollow::Layout => return self.relaid(id, from),
279	            _ => {}
280	        }
281	        // VR-27 (g): the strip and the Fit base come before the plan.
282	        let stripped;
283	        let source = if r.replace == Some(true) {
284	            stripped = self.replaced(id);
285	            &stripped
286	        } else {
287	            self
288	        };
289	        let path = match (r.follow, r.follow.following()) {
290	            (FramingFollow::Center, _) => fixed_framing(source, id, WhereEmpty::Center, zoom),
291	            (FramingFollow::Fit, _) => fixed_framing(source, id, WhereEmpty::Fit, 1.0),
292	            (FramingFollow::Speaker, _) => {
293	                let Some(subjects) = &r.subjects else {
294	                    return Ok(Outcome::Refused(no_subjects(id)));
295	                };
296	                let mics = r.mics.as_deref().unwrap_or(&[]);
297	                let empty = r.where_empty.unwrap_or_default();
298	                let faces = r.mic_faces.as_deref();
299	                match plan_speaker_framing(source, id, subjects, mics, faces, zoom, empty) {
300	                    Ok(path) => Some(path),
301	                    Err(why) => return Ok(Outcome::Refused(why)),
302	                }
303	            }
304	            (FramingFollow::Cursor, _) => {
305	                let Some(subjects) = &r.subjects else {
306	                    return Ok(Outcome::Refused(no_subjects(id)));
307	                };
308	                plan_cursor_framing(source, id, &subjects.cursor, zoom)
309	            }
310	            (_, Some(follow)) => {
311	                let Some(subjects) = &r.subjects else {
312	                    return Ok(Outcome::Refused(no_subjects(id)));
313	                };
314	                let request = FramingRequest {
315	                    follow,
316	                    zoom,
317	                    from_width: canvas.0,
318	                    from_height: canvas.1,
319	                    where_empty: r.where_empty.unwrap_or_default(),
320	                };
321	                plan_framing(source, id, subjects, &request, &FRAMING_TUNING)
322	            }
323	            (_, None) => None,
324	        };
325	        // No path is unreached: every arm the planner has is refused above.
326	        let Some(path) = path else {
327	            return Ok(Outcome::Refused(no_picture(id)));
328	        };
329	        let backdrop = r.backdrop.filter(|_| path.shows_fit);
330	        let original = Clip {
331	            video: Some(clip.video.clone().unwrap_or_default()),
332	            ..clip.clone()
333	        };
334	        if let Some(track) = backdrop {
335	            if let Err(why) = self.blurred_copy(&original, 0, 0) {
336	                return Ok(Outcome::Refused(why));
337	            }
338	            if self.track_index(track) >= self.track_index(clip.track) {
339	                return Ok(Outcome::Refused(format!(
340	                    "track {track} is not behind clip {id}'s track, so a backdrop there would \
341	                     cover it"
342	                )));
343	            }
344	        }
345	        if let (Some(_), Some(subjects)) = (r.follow.following(), &r.subjects) {
346	            if in_clip_time(clip, self, subjects).0.is_empty() {
347	                return Ok(Outcome::Refused(no_subjects(id)));
348	            }
349	        }
350	        if let (FramingFollow::Cursor, Some(subjects)) = (r.follow, &r.subjects) {
351	            if cursor_in_clip_time(clip, self, &subjects.cursor).is_empty() {
352	                return Ok(Outcome::Refused(no_subjects(id)));
353	            }
354	        }
355	        let (mut next, _) = source.composed(id, &path);
356	        if let Some(track) = backdrop {
357	            next = next.with_backdrop(&original, track)?;
358	        }
359	        self.finish(next)
360	    }
361	}
362	
363	/// Refusal (2)'s crop sentence.
364	fn no_picture(id: u32) -> String {
365	    format!("clip {id}'s crop or scale leaves no picture to frame")
366	}
367	
368	/// Refusal (6): a turned base, an action end turning the clip, or a spin.
369	fn turn_refusal(id: u32, clip: &Clip, video: &VideoProps) -> Option<String> {
370	    let upright = "framing works on an upright picture; only keep reframes it";
371	    if video.rotation != 0.0 {
372	        return Some(format!(
373	            "clip {id} is turned {}°, and {upright}",
374	            video.rotation
375	        ));
376	    }
377	    let turning = |a: &&Action| {
378	        a.end["video"]["rotation"]
379	            .as_f64()
380	            .is_some_and(|r| r != 0.0)
381	    };
382	    if let Some(action) = clip.actions.iter().find(turning) {
383	        return Some(format!(
384	            "clip {id}'s action {} turns it, and {upright}",
385	            action.id
386	        ));
387	    }
388	    let spins = video.motion.as_ref().is_some_and(|m| {
389	        [m.r#in, m.out]
390	            .iter()
391	            .flatten()
392	            .any(|e| e.kind == EdgeMotion::Spin)
393	            || m.during.is_some_and(|d| d.kind == DuringMotion::Spin)
394	    });
395	    spins.then(|| format!("clip {id} spins in its motion, and {upright}"))
396	}
